// Generated by build.rs from providers/*.toml and providers/fixtures/<key>/*.json.
include!(concat!(env!("OUT_DIR"), "/builtin_specs.rs"));

/// Where a loaded spec came from; printed in every step error.
#[derive(Clone)]
pub enum Origin {
    Builtin(&'static str),
    Override(PathBuf),
    /// A spec under test (check_spec, fixture replay) that is not loaded.
    Candidate,
}

impl Origin {
    pub fn kind(&self) -> &'static str {
        match self {
            Self::Builtin(_) => "builtin",
            Self::Override(_) => "override",
            Self::Candidate => "candidate",
        }
    }

    pub fn path(&self) -> String {
        match self {
            Self::Builtin(file) => format!("providers/{file}"),
            Self::Override(path) => path.display().to_string(),
            Self::Candidate => String::new(),
        }
    }
}

impl fmt::Display for Origin {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Candidate => f.write_str("candidate spec"),
            other => write!(f, "{} {}", other.kind(), other.path()),
        }
    }
}

/// An override file that failed to load; the built-in (if any) stays active.
#[derive(Clone, Serialize, JsonSchema)]
pub struct SpecProblem {
    pub file: String,
    pub error: String,
}

/// One consistent snapshot: built-in specs, `<home>/providers/*.toml` overrides on top, and the env.
pub struct Registry {
    providers: BTreeMap<String, Arc<Provider>>,
    pub env: Env,
    pub problems: Vec<SpecProblem>,
}

static BUILTIN: LazyLock<Result<Vec<(&'static str, Spec)>, String>> = LazyLock::new(|| {
    BUILTIN_SPECS
        .iter()
        .map(|(file, text)| Ok((*file, Spec::parse(text).map_err(|e| format!("built-in provider spec {file}: {e:#}"))?)))
        .collect()
});

/// The file's stamp when it was parsed, and the outcome; unchanged overrides are not parsed again.
type Parsed = HashMap<PathBuf, (FileStamp, Result<Spec, String>)>;
type FileStamp = (Option<SystemTime>, u64);

impl Registry {
    fn load(home: &Path, http: &reqwest::Client, stamp: &[(PathBuf, FileStamp)], parsed: &mut Parsed) -> Result<Self> {
        let env = Env::load(home)?;
        let builtin = BUILTIN.as_ref().map_err(|e| anyhow!("{e}"))?;
        let mut specs: BTreeMap<String, (Spec, Origin)> =
            builtin.iter().map(|(file, spec)| (spec.key.clone(), (spec.clone(), Origin::Builtin(file)))).collect();
        let mut problems = Vec::new();
        let overrides = &stamp[..stamp.len() - 1];
        parsed.retain(|path, _| overrides.iter().any(|(p, _)| p == path));
        for (path, file_stamp) in overrides {
            if parsed.get(path).is_none_or(|(s, _)| s != file_stamp) {
                let outcome = std::fs::read_to_string(path).map_err(Into::into).and_then(|t| Spec::parse(&t));
                match &outcome {
                    Ok(_) => tracing::info!("loaded provider spec {}", path.display()),
                    Err(e) => tracing::warn!("skipping {}: {e:#}", path.display()),
                }
                parsed.insert(path.clone(), (*file_stamp, outcome.map_err(|e| format!("{e:#}"))));
            }
            match parsed[path].1.clone() {
                Ok(spec) => {
                    specs.insert(spec.key.clone(), (spec, Origin::Override(path.clone())));
                }
                Err(error) => problems.push(SpecProblem { file: path.display().to_string(), error }),
            }
        }
        let providers = specs
            .into_iter()
            .map(|(key, (spec, origin))| (key, Arc::new(Provider::new(spec, origin, env.clone(), http.clone()))))
            .collect();
        Ok(Self { providers, env, problems })
    }

    pub fn get(&self, key: &str) -> Option<&Arc<Provider>> {
        self.providers.get(key)
    }

    pub fn iter(&self) -> impl Iterator<Item = &Arc<Provider>> {
        self.providers.values()
    }

    pub fn for_catalog(&self, provider_name: &str) -> Option<&Arc<Provider>> {
        self.iter().find(|p| p.spec.catalog.iter().any(|c| c == provider_name))
    }
}

/// The live registry. Reloads when `<home>/providers/*.toml` or `config.toml` change, so spec
/// fixes and new keys apply without a restart, also across separate stdio MCP processes.
pub struct Providers {
    home: PathBuf,
    http: reqwest::Client,
    state: RwLock<State>,
}

struct State {
    registry: Arc<Registry>,
    stamp: Vec<(PathBuf, FileStamp)>,
    parsed: Parsed,
    checked: Instant,
}

impl State {
    fn fresh(home: &Path, http: &reqwest::Client) -> Result<Self> {
        let stamp = stamp(home);
        let mut parsed = Parsed::new();
        let registry = Arc::new(Registry::load(home, http, &stamp, &mut parsed)?);
        Ok(Self { registry, stamp, parsed, checked: Instant::now() })
    }
}

const RECHECK: Duration = Duration::from_secs(1);

impl Providers {
    pub fn load(home: &Path, http: &reqwest::Client) -> Result<Self> {
        Ok(Self { home: home.to_owned(), http: http.clone(), state: RwLock::new(State::fresh(home, http)?) })
    }

    pub fn current(&self) -> Arc<Registry> {
        {
            let state = self.state.read().unwrap_or_else(|e| e.into_inner());
            if state.checked.elapsed() < RECHECK {
                return state.registry.clone();
            }
        }
        let mut state = self.state.write().unwrap_or_else(|e| e.into_inner());
        if state.checked.elapsed() < RECHECK {
            return state.registry.clone();
        }
        state.checked = Instant::now();
        let now = stamp(&self.home);
        if now != state.stamp {
            match Registry::load(&self.home, &self.http, &now, &mut state.parsed) {
                Ok(registry) => {
                    tracing::info!("provider specs or config changed, reloaded");
                    state.registry = Arc::new(registry);
                }
                Err(e) => tracing::warn!("reload failed, keeping previous specs: {e:#}"),
            }
            state.stamp = now;
        }
        state.registry.clone()
    }

    /// Reloads immediately (after this process wrote a spec).
    pub fn reload(&self) -> Result<Arc<Registry>> {
        let state = State::fresh(&self.home, &self.http)?;
        let registry = state.registry.clone();
        *self.state.write().unwrap_or_else(|e| e.into_inner()) = state;
        Ok(registry)
    }

    pub fn overrides_dir(&self) -> PathBuf {
        self.home.join("providers")
    }
}

fn override_files(home: &Path) -> Vec<PathBuf> {
    let mut files: Vec<PathBuf> = std::fs::read_dir(home.join("providers"))
        .into_iter()
        .flatten()
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|e| e == "toml"))
        .collect();
    files.sort();
    files
}

/// Override files, then `config.toml` last.
fn stamp(home: &Path) -> Vec<(PathBuf, FileStamp)> {
    override_files(home)
        .into_iter()
        .chain([home.join("config.toml")])
        .map(|p| {
            let meta = std::fs::metadata(&p).ok();
            let modified = meta.as_ref().and_then(|m| m.modified().ok());
            let len = meta.map_or(0, |m| m.len());
            (p, (modified, len))
        })
        .collect()
}

pub fn builtin_spec(key: &str) -> Option<(&'static str, &'static str)> {
    BUILTIN_SPECS.iter().copied().find(|(file, _)| file.strip_suffix(".toml") == Some(key))
}

#[cfg(test)]
mod tests {
    use std::collections::HashSet;

    use super::*;

    #[test]
    fn builtin_specs_are_valid_and_named_by_key() {
        let mut keys = HashSet::new();
        let mut catalog = HashSet::new();
        for (file, text) in BUILTIN_SPECS {
            let spec = Spec::parse(text).unwrap_or_else(|e| panic!("{file}: {e:#}"));
            assert_eq!(*file, format!("{}.toml", spec.key), "file name must equal key");
            assert!(keys.insert(spec.key.clone()), "duplicate key {}", spec.key);
            for name in &spec.catalog {
                assert!(catalog.insert(name.clone()), "{name} claimed by two specs");
            }
        }
    }

    #[test]
    fn overrides_hot_reload_and_report_problems() {
        let home = std::env::temp_dir().join(format!("ai-media-router-test-{}", uuid::Uuid::new_v4().simple()));
        std::fs::create_dir_all(home.join("providers")).unwrap();
        let providers = Providers::load(&home, &reqwest::Client::new()).unwrap();
        assert_eq!(providers.current().get("kie").unwrap().origin.kind(), "builtin");

        let text = BUILTIN_SPECS.iter().find(|(f, _)| *f == "kie.toml").unwrap().1.replace("kie.ai\"", "kie (fork)\"");
        std::fs::write(home.join("providers/kie.toml"), text).unwrap();
        std::fs::write(home.join("providers/broken.toml"), "key = ").unwrap();
        let registry = providers.reload().unwrap();
        assert_eq!(registry.get("kie").unwrap().origin.kind(), "override");
        assert_eq!(registry.problems.len(), 1);
        std::fs::remove_dir_all(&home).ok();
    }
}
